from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2
import json

ds = DataStore()
ds.open_for_scan('/root/distill_sparse_swiglu/wandb/offline-run-20260516_051217-06u4phga/run-06u4phga.wandb')

history = []
count = 0
while True:
    data = ds.scan_data()
    if data is None:
        break
    count += 1

    # Parse as Record
    record = wandb_internal_pb2.Record()
    try:
        record.ParseFromString(data)
        if record.HasField('history'):
            item = {}
            for kv in record.history.item:
                if kv.HasField('value_json'):
                    try:
                        item[kv.key] = json.loads(kv.value_json)
                    except:
                        item[kv.key] = kv.value_json
            if item:
                history.append(item)
    except:
        pass

print(f'Total records: {count}, history entries: {len(history)}')
if history:
    print(f'Keys in first entry: {sorted(history[0].keys())}')
    print(f'First entry: {json.dumps(history[0], indent=2)[:500]}')
    print(f'Last entry: {json.dumps(history[-1], indent=2)[:500]}')
